<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserProfile\Infrastructure\Driven;

use Psr\EventDispatcher\EventDispatcherInterface;
use Closure;
use Override;
use Throwable;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\UserProfile\Domain\Gateway\UserProfileWriteGateway;
use Civi\Lughauth\Features\Access\UserProfile\Infrastructure\Connector\Pdo\UserProfilePdoConnector;
use Civi\Lughauth\Features\Access\UserProfile\Domain\Gateway\UserProfileSlide;
use Civi\Lughauth\Features\Access\UserProfile\Domain\Gateway\UserProfileCursor;
use Civi\Lughauth\Features\Access\UserProfile\Domain\Gateway\UserProfileFilter;
use Civi\Lughauth\Features\Access\UserProfile\Domain\UserProfileRef;
use Civi\Lughauth\Features\Access\UserProfile\Domain\UserProfile;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\EntityChangelog\EntityChangelogService;

class UserProfileWriteRepositoryAdapter implements UserProfileWriteGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly UserProfilePdoConnector $conn,
        private readonly EventDispatcherInterface $dispatcher,
        private readonly EntityChangelogService $changelog,
    ) {
    }
    #[Override]
    public function resolveForUpdate(UserProfileRef $ref): ?UserProfile
    {
        return $this->conn->retrieveForUpdate(new UserProfileFilter(uids: [ $ref->uid() ]));
    }
    #[Override]
    public function listForUpdate(?UserProfileFilter $filter = null, ?UserProfileCursor $cursor = null): UserProfileSlide
    {
        $this->logDebug("List for update of User profile on adapter ");
        $span = $this->startSpan("List for update of User profile on adapter");
        try {
            $values = $this->conn->listForUpdate($filter, $cursor);
            $last = end($values);
            return new UserProfileSlide(function (UserProfileSlide $slide, ?UserProfileCursor$next) use ($filter) {
                return $this->listForUpdate($filter, $next);
            }, new UserProfileCursor($cursor?->limit() ?? 100, false !== $last ? $last->uid() : null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieveForUpdate(UserProfileFilter $filter): ?UserProfile
    {
        $this->logDebug("Retrieve for update of User profile on adapter ");
        $span = $this->startSpan("Retrieve for update of User profile on adapter");
        try {
            return $this->conn->retrieveForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function existsForUpdate(UserProfileFilter $filter): bool
    {
        $this->logDebug("Exists for update of User profile on adapter ");
        $span = $this->startSpan("Exists for update of User profile on adapter");
        try {
            return $this->conn->existsForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function countForUpdate(?UserProfileFilter $filter = null): int
    {
        $this->logDebug("Count for update of User profile on adapter ");
        $span = $this->startSpan("Count for update of User profile on adapter");
        try {
            return $this->conn->countForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function create(UserProfile $entity, ?Closure $verify = null): UserProfile
    {
        $this->logDebug("Count for User profile on adapter ");
        $span = $this->startSpan("Count for User profile on adapter");
        try {
            $created = $this->conn->create($entity, $verify);
            $this->dispatch($entity);
            $this->changelog->recordChange('user-profile', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $created;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function update(UserProfileRef $ref, UserProfile $entity): UserProfile
    {
        $this->logDebug("Count for User profile on adapter ");
        $span = $this->startSpan("Count for User profile on adapter");
        try {
            $updated = $this->conn->update($entity);
            $this->dispatch($entity);
            $this->changelog->recordChange('user-profile', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $updated;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function delete(UserProfile $entity): bool
    {
        $this->logDebug("Count for User profile on adapter ");
        $span = $this->startSpan("Count for User profile on adapter");
        try {
            $result = $this->conn->delete($entity);
            $this->dispatch($entity);
            $this->changelog->recordDeletion('user-profile', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $result;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneForUpdateByUid(string $uid): ?UserProfile
    {
        $this->logDebug("Find on by uid for User profile on adapter");
        $span = $this->startSpan("Find on by uid for User profile on adapter");
        try {
            return $this->conn->retrieveForUpdate(new UserProfileFilter(uids: [$uid]));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneForUpdateByUser(UserRef $user): ?UserProfile
    {
        $this->logDebug("Find on by user for User profile on adapter");
        $span = $this->startSpan("Find on by user for User profile on adapter");
        try {
            return $this->conn->retrieveForUpdate(new UserProfileFilter(user: $user));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function dispatch(UserProfile $entity): void
    {
        $this->logDebug("Count for User profile on adapter ");
        $span = $this->startSpan("Count for User profile on adapter");
        try {
            foreach ($entity->getTheEvents() as $event) {
                $this->dispatcher->dispatch($event);
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
